```tsx
import { useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  Button,
  Badge,
  Alert,
  KeyBar,
} from '@nexti/ds';

type Estado = 'exito' | 'rechazado' | 'sinDatos';

const ejemplos: Record<
  Estado,
  { RORDEN: string; RCOMIS: string; RMOVIM: string; RMENS: string }
> = {
  exito: {
    RORDEN: '0004582',
    RCOMIS: '    12.50',
    RMOVIM: '     73910',
    RMENS: 'PAGO APLICADO CORRECTAMENTE',
  },
  rechazado: {
    RORDEN: '0004583',
    RCOMIS: '     0.00',
    RMOVIM: '         0',
    RMENS: 'PAGO RECHAZADO - SALDO INSUFICIENTE',
  },
  sinDatos: {
    RORDEN: '',
    RCOMIS: '',
    RMOVIM: '',
    RMENS: '',
  },
};

export default function PagoResultado({
  navigate,
}: {
  navigate: (to: string) => void;
}) {
  const [estado, setEstado] = useState<Estado>('exito');
  const datos = ejemplos[estado];

  const nuevoPago = () => navigate('SCR-PAGOORD');
  const volverMenu = () => navigate('SCR-PAGOMEN');

  return (
    <Screen
      title="Resultado del pago"
      code="PAGORES"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Nuevo pago', onPress: nuevoPago, primary: true },
            { key: 'PF3', label: 'Menú', onPress: volverMenu },
          ]}
        />
      }
    >
      <Stack>
        <Row>
          <Button variant="ghost" onClick={() => setEstado('exito')}>
            Ver pago aplicado
          </Button>
          <Button variant="ghost" onClick={() => setEstado('rechazado')}>
            Ver pago rechazado
          </Button>
          <Button variant="ghost" onClick={() => setEstado('sinDatos')}>
            Ver sin datos
          </Button>
        </Row>

        {estado === 'exito' && (
          <Alert tone="success">El pago fue procesado. Revise el detalle a continuación.</Alert>
        )}
        {estado === 'rechazado' && (
          <Alert tone="error">El pago no pudo ser procesado. Revise el resultado.</Alert>
        )}
        {estado === 'sinDatos' && (
          <Alert tone="warning">
            No hay un resultado de pago para mostrar. Inicie un nuevo pago.
          </Alert>
        )}

        <Card title="Resultado del pago">
          <Grid columns={2}>
            <div data-field="RORDEN">
              <TextField
                label="Orden"
                hint="Número de orden, 7 dígitos"
                numeric
                maxLength={7}
                value={datos.RORDEN}
                onChange={() => {}}
                readOnly
              />
            </div>
            <div data-field="RCOMIS">
              <TextField
                label="Comisión"
                hint="Formato ZZZ,ZZ9.99"
                numeric
                maxLength={10}
                value={datos.RCOMIS.trim()}
                onChange={() => {}}
                readOnly
              />
            </div>
            <div data-field="RMOVIM">
              <TextField
                label="Movimiento"
                hint="Número de movimiento, hasta 10 dígitos"
                numeric
                maxLength={10}
                value={datos.RMOVIM.trim()}
                onChange={() => {}}
                readOnly
              />
            </div>
            <div data-field="RMENS">
              <Stack>
                <TextField
                  label="Resultado"
                  maxLength={40}
                  value={datos.RMENS}
                  onChange={() => {}}
                  readOnly
                />
                {estado !== 'sinDatos' && (
                  <Badge>{estado === 'exito' ? 'Aplicado' : 'Rechazado'}</Badge>
                )}
              </Stack>
            </div>
          </Grid>
        </Card>

        <Row>
          <Button variant="primary" shortcut="ENTER" onClick={nuevoPago}>
            Nuevo pago
          </Button>
          <Button variant="secondary" shortcut="PF3" onClick={volverMenu}>
            Menú
          </Button>
        </Row>
      </Stack>
    </Screen>
  );
}
